<?php
declare(strict_types=1);
require_once __DIR__.'/includes/iniciar.php';
$cliente=exigir_cliente();$cid=(int)$cliente['id'];$pedidoId=(int)($_GET['pedido']??0);
$st=$pdo->prepare("SELECT c.*,o.order_number FROM conversations c INNER JOIN orders o ON o.id=c.order_id WHERE c.customer_id=? ORDER BY c.last_message_at DESC,c.id DESC");$st->execute([$cid]);$conversas=$st->fetchAll();
if(!$pedidoId&&$conversas)$pedidoId=(int)$conversas[0]['order_id'];
$st=$pdo->prepare("SELECT c.*,o.order_number FROM conversations c INNER JOIN orders o ON o.id=c.order_id WHERE c.customer_id=? AND c.order_id=? LIMIT 1");$st->execute([$cid,$pedidoId]);$conversa=$st->fetch();
if($_SERVER['REQUEST_METHOD']==='POST'&&$conversa){verify_csrf();$body=trim($_POST['body']??'');if($body!==''&&strlen($body)<=5000&&$conversa['status']==='open'){$m=$pdo->prepare("INSERT INTO messages (conversation_id,sender_type,customer_sender_id,user_sender_id,body,created_at) VALUES (?,'customer',?,NULL,?,NOW())");$m->execute([(int)$conversa['id'],$cid,$body]);$u=$pdo->prepare("UPDATE conversations SET last_message_at=NOW(),updated_at=NOW() WHERE id=? AND customer_id=?");$u->execute([(int)$conversa['id'],$cid]);}redirect('chat.php?pedido='.$pedidoId);}
$mensagens=[];if($conversa){$m=$pdo->prepare("SELECT m.*,u.name AS staff_name FROM messages m LEFT JOIN users u ON u.id=m.user_sender_id WHERE m.conversation_id=? ORDER BY m.created_at ASC,m.id ASC");$m->execute([(int)$conversa['id']]);$mensagens=$m->fetchAll();}
$tituloPagina='Conversas';require __DIR__.'/includes/header-marketplace.php';
?>
<div class="container section"><h1 class="page-title">Conversas sobre os pedidos</h1><div class="two-col"><aside class="sidebar"><h3>Os teus pedidos</h3><?php foreach($conversas as $c):?><p><a class="category-list <?=((int)$c['order_id']===$pedidoId?'active':'')?>" href="chat.php?pedido=<?=(int)$c['order_id']?>"><?=e($c['order_number'])?></a></p><?php endforeach;?></aside><section><?php if(!$conversa):?><div class="empty">Ainda não existe conversa associada a este pedido.</div><?php else:?><h2><?=e($conversa['order_number'])?></h2><div class="chat-box"><?php foreach($mensagens as $m):$mine=$m['sender_type']==='customer';?><div class="chat-message <?=$mine?'mine':''?>"><?=nl2br(e($m['body']))?><small><?=$mine?'Tu':e($m['staff_name']??'Equipa GPM')?> · <?=e($m['created_at'])?></small></div><?php endforeach;?></div><?php if($conversa['status']==='open'):?><form method="post" class="panel" style="padding:15px;margin-top:12px"><?=csrf_field()?><div class="field"><label>Mensagem</label><textarea name="body" rows="3" maxlength="5000" required></textarea></div><button class="btn-primary" type="submit">Enviar mensagem</button></form><?php else:?><div class="alert">Esta conversa foi encerrada.</div><?php endif;?><?php endif;?></section></div></div>
<?php require __DIR__.'/includes/footer-marketplace.php';?>
